import{c as e,S as r,j as a,m as l}from"./chunks/framework.8aa1YH_s.js";const g=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 14: Kelime Türleri - Zamirler (Adıllar)","description":"","frontmatter":{},"headers":[],"relativePath":"14 Kelime Türleri - Zamirler (Adıllar).md","filePath":"14 Kelime Türleri - Zamirler (Adıllar).md"}'),n={name:"14 Kelime Türleri - Zamirler (Adıllar).md"};function m(t,i,s,o,d,k){return r(),a("div",null,[...i[0]||(i[0]=[l('<h1 id="turk-dil-bilgisi-serisi-14-kelime-turleri-zamirler-adıllar" tabindex="-1">Türk Dil Bilgisi Serisi - 14: Kelime Türleri - Zamirler (Adıllar) <a class="header-anchor" href="#turk-dil-bilgisi-serisi-14-kelime-turleri-zamirler-adıllar" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 14: Kelime Türleri - Zamirler (Adıllar)”">​</a></h1><p>Kelime türleri serimizde isimleri ve sıfatları geride bıraktık. Bu yazımızda, isim olmadıkları halde cümle içinde ismin yerine geçen, isimlerin yüklendiği tüm görevleri gizlice üstlenen <strong>Zamirler (Adıllar)</strong> konusunu ele alıyoruz.</p><p>Prof. Dr. Muharrem Ergin’e göre zamirler, bir varlığın kalıcı adı değildir. Onlar, konuşma anında geçici olarak bir veya birden fazla ismin yerine kendilerini ikame eden, isimler gibi çekim eklerini (<code>-lar</code>, hal ekleri, iyelik ekleri) rahatça alabilen joker kelimelerdir.</p><p>Muharrem Ergin sistematiğinde zamirler <strong>iki ana grupta</strong> (Kelime halindeki zamirler ve Ek halindeki zamirler) incelenir:</p><hr><h2 id="_1-kelime-halindeki-zamirler" tabindex="-1">1. Kelime Halindeki Zamirler <a class="header-anchor" href="#_1-kelime-halindeki-zamirler" aria-label="Permalink to “1. Kelime Halindeki Zamirler”">​</a></h2><p>Cümlede bağımsız birer kelime olarak bulunan ve doğrudan bir veya birden fazla ismin yerini tutan zamirlerdir. 4 alt gruba ayrılırlar:</p><h3 id="a-sahıs-kisi-zamirleri" tabindex="-1">A) Şahıs (Kişi) Zamirleri <a class="header-anchor" href="#a-sahıs-kisi-zamirleri" aria-label="Permalink to “A) Şahıs (Kişi) Zamirleri”">​</a></h3><p>Doğrudan doğruya insan isimlerinin yerini tutan zamirlerdir. Türkçede 3 tekil, 3 çoğul olmak üzere <strong>6 asli şahıs zamiri</strong> vardır:</p><ul><li><strong>Ben, sen, o, biz, siz, onlar</strong></li><li><em>Örnekler:</em> <strong>Ben</strong> kodu yazdım, <strong>onlar</strong> maça gitti.</li></ul><blockquote><p><strong>⚠️ Önemli Not (Kendi Zamiri):</strong> &gt; Muharrem Ergin sistematiğinde <strong>&quot;kendi&quot;</strong> kelimesi <strong>Dönüşlülük Zamiri</strong> olarak adlandırılır ve şahıs zamirlerinin içinde değerlendirilir. Cümleye pekiştirme anlamı katar: <em>Bu projeyi <strong>kendim</strong> yaptım.</em></p></blockquote><h3 id="b-isaret-gosterme-zamirleri" tabindex="-1">B) İşaret (Gösterme) Zamirleri <a class="header-anchor" href="#b-isaret-gosterme-zamirleri" aria-label="Permalink to “B) İşaret (Gösterme) Zamirleri”">​</a></h3><p>Varlıkların isimlerini doğrudan söylemek yerine, onları işaret yoluyla karşılayan zamirlerdir.</p><ul><li><strong>Bu, şu, o, bunlar, şunlar, onlar, burası, şurası, orası...</strong></li><li><em>Örnek:</em> <strong>Bunu</strong> masaya bırak, <strong>şunları</strong> çöpe at.</li></ul><blockquote><p><strong>💡 Sıfatla Karıştırma Akıllı İpucu:</strong> &gt; &quot;O&quot; ve &quot;Bu&quot; gibi kelimeler bir ismin önündeyse ve ek almadıysa <strong>sıfattır</strong> (<em>Bu ev</em>). İsmin yerini tutuyorsa ve çekim eki aldıysa <strong>zamirdir</strong> (<em>Bunu aldım</em>).</p></blockquote><h3 id="c-belgisiz-zamirler" tabindex="-1">C) Belgisiz Zamirler <a class="header-anchor" href="#c-belgisiz-zamirler" aria-label="Permalink to “C) Belgisiz Zamirler”">​</a></h3><p>Hangi isimlerin yerini tuttuğu tam olarak net olmayan, belirsiz, aşağı yukarı bir çokluğu veya hiçliği ifade eden zamirlerdir.</p><ul><li><strong>Herkes, kimse, biri, birkaçı, birçoğu, hepsi, tümü, falan, şey...</strong></li><li><em>Örnekler:</em> <strong>Herkes</strong> toplantıya katıldı. <strong>Birkaçı</strong> henüz gelmedi.</li></ul><h3 id="d-soru-zamirleri" tabindex="-1">D) Soru Zamirleri <a class="header-anchor" href="#d-soru-zamirleri" aria-label="Permalink to “D) Soru Zamirleri”">​</a></h3><p>İsimlerin yerini soru yoluyla tutan zamirlerdir. Bu sorulara verilecek cevaplar da yine bir isim veya zamirdir.</p><ul><li><strong>Kim, ne, hangisi, kaçı, nereye, nerede...</strong></li><li><em>Örnekler:</em> Pazardan <strong>ne</strong> aldın? (<em>Elma aldım</em>). Bu anahtar <strong>kimin</strong>? (<em>Mehmet&#39;in</em>).</li></ul><hr><h2 id="_2-ek-halindeki-zamirler" tabindex="-1">2. Ek Halindeki Zamirler <a class="header-anchor" href="#_2-ek-halindeki-zamirler" aria-label="Permalink to “2. Ek Halindeki Zamirler”">​</a></h2><p>Kelimeden bağımsız olmayıp, kelimenin sonuna eklenerek bir ismin yerini tutan yapılardır. 2&#39;ye ayrılırlar:</p><h3 id="a-iyelik-zamirleri-aitlik-bildiren-ekler" tabindex="-1">A) İyelik Zamirleri (Aitlik Bildiren Ekler) <a class="header-anchor" href="#a-iyelik-zamirleri-aitlik-bildiren-ekler" aria-label="Permalink to “A) İyelik Zamirleri (Aitlik Bildiren Ekler)”">​</a></h3><p>İsim çekim eklerinde gördüğümüz iyelik ekleri, aslında o nesnenin kime ait olduğunu göstererek bir şahsın yerini tuttukları için Muharrem Ergin tarafından &quot;ek halindeki zamir&quot; olarak nitelendirilir.</p><ul><li><em>Örnek:</em> Kalem-<strong>im</strong> (Benim ismimin yerini tutan bir ek var).</li></ul><h3 id="b-ilgi-zamiri-ki" tabindex="-1">B) İlgi Zamiri (<code>-ki</code>) <a class="header-anchor" href="#b-ilgi-zamiri-ki" aria-label="Permalink to “B) İlgi Zamiri (-ki)”">​</a></h3><p>Daha önce bahsedilen bir ismin tekrar edilmesini önlemek amacıyla, o ismin yerini tutan kalıplaşmış <strong><code>-ki</code></strong> ekidir. Kendisinden önce mutlaka bir tamlayan eki (<code>-ın/-in</code>) ister.</p><ul><li><em>Örnek:</em> Senin bilgisayarın hızlı, benim<strong>ki</strong> yavaş. (Buradaki <code>-ki</code>, &quot;bilgisayar&quot; isminin yerini tutmuştur).</li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Prof. Dr. Muharrem Ergin&#39;in tasnifiyle zamirler, dildeki tasarruf (en az çaba) ilkesinin en harika örnekleridir. Sayfalarca sürecek isim tekrarlarını tek bir &quot;o&quot;, &quot;bu&quot; veya &quot;herkes&quot; kelimesiyle çözmemizi sağlarlar. Zamiri sıfattan ayıran en büyük özellik çekim eki alabilmesi ve tek başına bir isim gibi cümle ögesi (özne, nesne vb.) olabilmesidir.</p><p>Zamirler vagonunu da başarıyla kilitledik aslanım!</p><p>Serimizin 15. bölümünde, isim soylu kelimelerin son durağı olan, fiilleri ve sıfatları dereceleyen muazzam bir türe geçiyoruz: <strong>&quot;Zarflar (Belirteçler)&quot;</strong>.</p><p>Hazırsan komutunu ver, sayfayı çevirelim!</p>',36)])])}const h=e(n,[["render",m]]);export{g as __pageData,h as default};
